String lcp(Trie t) {
    StringBuilder sb = new StringBuilder();
    Trie.Node cur = t.root;
    while (true) {
        int only = -1, kids = 0;
        for (int c = 0; c < 26; c++)
            if (cur.next[c] != null) { kids++; only = c; }
        if (kids != 1) break;
        sb.append((char) ('a' + only));
        cur = cur.next[only];
    }
    return sb.toString();
}

