public void erase(String w) {        // assumes w was inserted
    Node cur = root;
    for (char ch : w.toCharArray()) {
        cur = cur.next[ch - 'a'];
        cur.prefixCount--;
    }
    cur.endCount--;
}

int findMaximumXOR(int[] nums) {
    BitTrie t = new BitTrie();
    int best = 0;
    for (int x : nums) {
        best = Math.max(best, t.maxXor(x));   // query first
        t.insert(x);                          // then insert
    }
    return best;
}
